mapper.update:
update shopping_cart
set number=number+1
where user_id=#{userId}
 and dish_id=#{dishId}
 and setmeal_id= #{setmealId}
 and dish_flavor= #{dishFlavor}

update shopping_cart
set number=number-1
where user_id= #{userId}
 and dish_id= #{dishId}
 and setmeal_id= #{setmealId}
 and dish_flavor= #{dishFlavor}

mapper.delete:
delete from shopping_cart
where user_id= #{userId}
 and dish_id= #{dishId}
 and setmeal_id= #{setmealId}
 and dish_flavor= #{dishFlavor}

mapper.select:
select count(*) from shopping_cart
where user_id=#{userId}
 and dish_id=#{dishId}
 and setmeal_id= #{setmealId}
 and dish_flavor= #{dishFlavor}

select number from shopping_cart
where user_id= #{userId}
 and dish_id= #{dishId}
 and setmeal_id= #{setmealId}
 and dish_flavor= #{dishFlavor}
